contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: callerIsOwner indicates whether InvMutTest should act as owner (it always is, since c was deployed fresh by the checker with InvMutTest as deployer);
    // receiver is target address; amount is Ether to transfer from c to receiver.
    function run(address payable receiver, uint256 amount, bool sendFromTest) public payable {
        require(true);
        // Ensure this contract has enough balance only if we intend to fund c via payable to its constructor?
        // According to the harness, c was freshly deployed with InvMutTest as deployer, so InvMutTest is the owner.
        // We need to ensure c has enough balance to cover the transfer attempt. Send some Ether into c first if amount > 0.
        if (amount > 0) {
            // transfer amount to c so it can later send it out; ensure this contract has enough balance
            require(address(this).balance >= amount, "insufficient balance to fund c");
            (bool sent, ) = address(c).call{value: amount}("");
            require(sent, "funding c failed");
        }

        // read balance before
        uint256 before = address(c).balance;

        // call sendTo and capture whether it reverted
        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after = address(c).balance;

        // Rule: if call reverted then c's balance unchanged; otherwise (call succeeded) then:
        // - receiver must not be zero
        // - amount must be > 0
        // - c's balance decreased by exactly amount
        // Note: owner is this contract (deployer), so sendFromTest parameter is unused for interaction; kept as input to vary symbolic space.
        assert(
            (reverted && after == before) ||
            (!reverted && receiver != address(0) && amount > 0 && before >= amount && after == before - amount)
        );
    }

    receive() external payable {}
}

